using System;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class RestoreAndInspectClothing {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("User controls Play Mode: Edit Mode required");
 var fbx=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2_73_Baked.fbx");var source=fbx.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_body_lod0_mesh");
 var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab");try{root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name==source.name).sharedMesh=source.sharedMesh;PrefabUtility.SaveAsPrefabAsset(root,"Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab");AssetDatabase.SaveAssets();}finally{PrefabUtility.UnloadPrefabContents(root);}
 var report=SceneManager.GetActiveScene().GetRootGameObjects().Where(x=>new[]{"Ethan_V2_73_Baked","Ethan","Jiwoo_Normalized"}.Contains(x.name)).Select(x=>new{name=x.name,active=x.activeSelf,renderers=x.GetComponentsInChildren<SkinnedMeshRenderer>(true).Select(r=>new{name=r.name,mesh=r.sharedMesh.name,enabled=r.enabled,active=r.gameObject.activeInHierarchy,scale=r.transform.lossyScale.ToString("F4"),root=r.rootBone?r.rootBone.name:null,rootScale=r.rootBone?r.rootBone.lossyScale.ToString("F4"):null,bounds=r.localBounds.ToString("F4"),meshBounds=r.sharedMesh.bounds.ToString("F4"),bones=r.bones.Length,missingBones=r.bones.Count(b=>!b),materials=r.sharedMaterials.Select(m=>m?m.name:null).ToArray(),quality=r.quality.ToString(),updateOffscreen=r.updateWhenOffscreen}).ToArray(),scripts=x.GetComponentsInChildren<MonoBehaviour>(true).Where(c=>c).Select(c=>c.GetType().Name).Distinct().ToArray()}).ToArray();System.IO.File.WriteAllText("Data/EthanV2/ClothingRepair/scene_diagnosis.json",JsonConvert.SerializeObject(report,Formatting.Indented));return report;}
}
